import{_ as n,l as o,o as e,c as l,v as t,p as s,x as i,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"SELinux 类型强制","description":"","frontmatter":{"title":"SELinux 类型强制","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/selinux-type-enforcement.md","filePath":"cs/selinux-type-enforcement.md","lastUpdated":1789023840000}'),u={name:"cs/selinux-type-enforcement.md"};function h(E,a,m,_,x,f){const r=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="selinux-类型强制" tabindex="-1">SELinux 类型强制 <a class="header-anchor" href="#selinux-类型强制" aria-label="Permalink to &quot;SELinux 类型强制&quot;">​</a></h1><div class="epigraph"><p>类型强制给进程与文件打类型标签，规则只允许指定的类型对流。即便进程以 root 跑，也不能任意读未允许的客体。策略是规格，不是建议。</p><footer>—— Loscocco and Smalley, Integrating Flexible Support for Security Policies into the Linux Operating System, USENIX 2001；NSA SELinux</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/red-blue-team">红蓝</a>结束网络防御。系统单元从强制访问起。主干<a href="/cs/dac-mac-rbac">DAC/MAC/RBAC</a>已给 MAC 名字。缺口是 <strong>SELinux 类型强制</strong>如何落到 Linux：标签、允许规则、最小特权。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>DAC 的 root 全能。MAC：httpd_t 只能碰 httpd_sys_content_t 一类。缺口是策略编写与 permissive/enforcing，不是关闭 SELinux 当排错默认。</p><h3 id="容器" tabindex="-1">容器 <a class="header-anchor" href="#容器" aria-label="Permalink to &quot;容器&quot;">​</a></h3><p>容器常带自己的类型；错误的 unconfined 等于关掉这层。</p><p><span class="marginnote">Flask/TE。本课不写如何逃策略的步骤。提权下一课谈能力与 sudo 面。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画主体类型、客体类型、允许。对照 AppArmor 路径名策略点名。下一课 Linux 提权路径：能力、SUID、配置。</p>',12)),(e(),s(p,null,{default:i(()=>[d(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SUB%5B%22%E8%BF%9B%E7%A8%8B%E7%B1%BB%E5%9E%8B%22%5D%20--%3E%20RULE%5B%22%E5%85%81%E8%AE%B8%E8%A7%84%E5%88%99%22%5D%0A%20%20OBJ%5B%22%E6%96%87%E4%BB%B6%E7%B1%BB%E5%9E%8B%22%5D%20--%3E%20RULE%0A%20%20RULE%20--%3E%20DENY%5B%22%E6%9C%AA%E5%85%81%E8%AE%B8%E5%88%99%E6%8B%92%E7%BB%9D%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>引用监视器在内核。策略错误会拒服务，于是有人关 SELinux——那是可用性打完整。提权课假设这层可能被配错。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写逃逸策略。Linux 提权路径下一课只讲机制与硬化，不给利用步骤。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>红蓝之后，系统层用 TE 限制即便是 root 的进程。</li><li>标签加允许规则；enforcing 才是策略。</li><li>关 SELinux 排错是把 MAC 撤掉。</li><li>下一课 Linux 提权路径。</li><li>出处：Loscocco and Smalley, 2001；对照 <a href="/cs/dac-mac-rbac">dac-mac-rbac</a>。</li></ul>',8))])}const A=n(u,[["render",h]]);export{S as __pageData,A as default};
